-- Reactor Control 0.1.41 compact offline install. Basalt2 is MIT licensed.
-- Embedded payloads use fixed-width 12-bit LZW, encoded as base64. No downloads
-- or external decompressor are needed. Validate size and Adler-32 before use.
local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local digits={};for i=1,#alphabet do digits[alphabet:sub(i,i)]=i-1 end
local function unpackFile(item)
  local bytes,bits,value={},0,0
  for char in item[3]:gmatch('.') do
    if char~='=' then
      local digit=assert(digits[char],'Damaged package encoding')
      value=value*64+digit;bits=bits+6
      if bits>=8 then bits=bits-8;bytes[#bytes+1]=string.char(math.floor(value/2^bits));value=value%2^bits end
    end
  end
  local packed=table.concat(bytes);local dictionary={}
  local function reset() dictionary={};for i=0,255 do dictionary[i]=string.char(i) end end
  reset()
  local nextCode,offset,half,previous=256,1,false,nil
  local output={}
  while offset+1<=#packed do
    local code
    if not half then code=packed:byte(offset)*16+math.floor(packed:byte(offset+1)/16);half=true
    else
      if offset+2>#packed then break end
      code=(packed:byte(offset+1)%16)*256+packed:byte(offset+2);offset=offset+3;half=false
    end
    local entry=dictionary[code]
    if not entry and previous and code==nextCode then entry=previous..previous:sub(1,1) end
    assert(entry,'Damaged package dictionary')
    output[#output+1]=entry
    if previous then
      if nextCode<4096 then dictionary[nextCode]=previous..entry:sub(1,1);nextCode=nextCode+1
      else reset();nextCode=256 end
    end
    previous=entry
  end
  local data=table.concat(output);assert(#data==item[1],'Damaged package length')
  local a,b=1,0
  for i=1,#data do a=(a+data:byte(i))%65521;b=(b+a)%65521 end
  assert(b*65536+a==item[2],'Damaged package checksum')
  return data
end
local function writeFile(path,data)
  local parent=fs.getDir(path)
  if not fs.exists(parent) then fs.makeDir(parent) end
  local f=assert(fs.open(path,'w'),'Cannot write '..path)
  local ok,err=pcall(f.write,data)
  local closed,closeError=pcall(f.close)
  assert(ok,err);assert(closed,closeError)
end
local function checkSpace(path,required)
  -- Allow allocation overhead and room for subsequent saved settings.
  required=required+16384
  local existing=path
  while not fs.exists(existing) do
    local parent=fs.getDir(existing)
    assert(parent~=existing,'Cannot locate installation drive')
    existing=parent
  end
  local available=fs.getFreeSpace(existing)
  if type(available)=='number' and available<required then
    error(string.format('Not enough disk space: need about %d KB free; have %d KB. No installation files changed. Move old installer/update downloads out of this computer, then retry.',math.ceil(required/1024),math.floor(available/1024)),0)
  end
end

local files = {
["main.lua"] = {2547, 2492223770, ""},
["agent.lua"] = {2217, 1780014310, ""},
["startup.lua"] = {1668, 1809592713, ""},
["diagnostics.lua"] = {3000, 4260352448, ""},
["config.lua"] = {1669, 1979911905, ""},
["THIRD_PARTY_NOTICES.txt"] = {741, 3367174379, ""},
["lib/app.lua"] = {17894, 3177144960, ""},
["lib/backend.lua"] = {2071, 954703294, ""},
["lib/calibration.lua"] = {2294, 1069025170, ""},
["lib/companion.lua"] = {1535, 1264912187, ""},
["lib/companion_ui.lua"] = {8090, 3823233095, ""},
["lib/control.lua"] = {19072, 3085602589, ""},
["lib/demo.lua"] = {2587, 1463896609, ""},
["lib/devices.lua"] = {9471, 2623698339, ""},
["lib/display.lua"] = {1207, 1880857776, ""},
["lib/network.lua"] = {3007, 3413749726, ""},
["lib/presentation.lua"] = {4873, 3067890391, ""},
["lib/settings.lua"] = {5577, 3751304589, ""},
["lib/setup_ui.lua"] = {7389, 293412755, ""},
["lib/startup.lua"] = {5823, 782731984, ""},
["lib/ui.lua"] = {18976, 3418504965, ""},
["lib/ui_widgets.lua"] = {1934, 1491363641, ""},
["lib/util.lua"] = {854, 146084236, ""},
["lib/version.lua"] = {16, 744948785, "ByBlB0B1ByBuAgAiAwAuAxAuA0AxAiAK"},
["vendor/basalt.lua"] = {283779, 445938897, ""},
["vendor/BASALT-LICENSE.txt"] = {1067, 779113509, ""},
}
local arguments = {...}

local function parseArguments()
  local destination, role, controllerId
  local index = 1
  while index <= #arguments do
    local argument = arguments[index]
    if argument == "--controller" or argument == "--companion" then
      assert(not role, "Choose only one installation role")
      role = argument == "--controller" and "controller" or "companion"
      if role == "companion" then
        index = index + 1
        controllerId = tonumber(arguments[index])
        assert(controllerId, "--companion requires the main controller computer ID")
      end
    elseif argument == "--help" then
      print("Usage: installer [DIRECTORY] [--controller | --companion CONTROLLER_ID]")
      print("Without a role flag, the installer asks which role to start at boot.")
      return nil, nil, nil, true
    else
      assert(argument:sub(1, 2) ~= "--" and not destination,
        "Unknown or extra argument: " .. argument)
      destination = argument
    end
    index = index + 1
  end
  return shell.resolve(destination or "reactor-control"), role, controllerId, false
end

local function packageSize()
  local required = 0
  for _, item in pairs(files) do
    required = required + math.max(item[1], 1024) + 2048
  end
  return required
end

local destination, role, controllerId, helpOnly = parseArguments()
if helpOnly then
  return
end

assert(not fs.exists(destination),
  "Destination exists. Use the updater to preserve your settings.")
local stage = destination .. "-install-0.1.41.tmp"
assert(not fs.exists(stage),
  "Previous staging directory exists: " .. stage .. ". Inspect it before retrying.")
checkSpace(destination, packageSize())

-- Use the bundled setup module without importing another installation's modules.
local startupSource = unpackFile(files["lib/startup.lua"])
local Startup = assert(load(startupSource, "startup setup", "t", _ENV))()
local selected = role and Startup.check(destination, role, controllerId)
  or Startup.choose(destination)

local installed, installError = pcall(function()
  fs.makeDir(stage)
  for name, item in pairs(files) do
    writeFile(fs.combine(stage, name), unpackFile(item))
  end
  fs.move(stage, destination)
end)
if not installed then
  -- This directory was created by this attempt and contains only package data.
  if fs.exists(stage) then
    fs.delete(stage)
  end
  error("Installation failed; destination was not created: " .. tostring(installError), 0)
end

print("Installed Reactor Control 0.1.41 in " .. destination)
local configured, setupError = pcall(
  Startup.enable, destination, selected.role, selected.owner)
if not configured then
  error("Program installed, but startup setup failed: " .. tostring(setupError)
    .. "\nAfter fixing the error, run " .. destination
    .. "/startup setup. Do not reinstall.", 0)
end

local pairing = selected.owner and (" for controller #" .. selected.owner) or ""
print("Startup enabled: " .. selected.role .. pairing)
if selected.role == "companion" then
  print("On the main controller: Setup > Peers > add ID " .. os.getComputerID())
else
  print("First launch is Manual. Choose storage and enable Auto when ready.")
end
print("Run " .. destination .. "/startup run now, or reboot to test startup.")
print("You may now remove this installer download to reclaim disk space.")
